// embed.js -- the last step of build.sh: strip the two modules and write them,
// base64-encoded, into the JS module the classifier's worker imports.
//
//   node embed.js <simd.raw.wasm> <scalar.raw.wasm> <out.js>
//
// Base64 inside a JS module rather than a .wasm file beside the bundle, as
// ../pcmv4 does: the worker bundle then carries its code, and no server,
// app or proxy needs a route or a MIME type for it.
//
// Custom sections are dropped: the linker keeps "producers", which names the
// compiler version and would make two builds of the same code differ.
//
// The generated file records a hash of the sources it was built from, so
// test.js can tell a stale build from a current one without a toolchain.

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function readLEB(buf, off) {
    let v = 0, shift = 0;
    for (;;) {
        const b = buf[off++];
        v += (b & 0x7f) * 2 ** shift;
        if (b < 0x80) return [v, off];
        shift += 7;
    }
}

function stripCustom(buf) {
    if (buf.readUInt32LE(0) !== 0x6d736100) throw new Error('not a wasm module');
    const parts = [buf.subarray(0, 8)];
    let off = 8;
    while (off < buf.length) {
        const start = off;
        const id = buf[off++];
        const [size, body] = readLEB(buf, off);
        off = body + size;
        if (id !== 0) parts.push(buf.subarray(start, off));
    }
    return Buffer.concat(parts);
}

// Must list every file whose content reaches the binaries or this output.
const SOURCES = ['audioclass.h', 'api.c', 'pt.c', 'model.c', 'resample.c', 'verdict.c', 'kernels.c',
    'gomath.c', 'shim.c', 'gen_labels.js', 'build.sh', 'embed.js', 'audioset_labels.csv'];

function sourceHash(dir) {
    const h = crypto.createHash('sha256');
    for (const f of SOURCES) {
        h.update(f + '\0');
        h.update(fs.readFileSync(path.join(dir, f)));
        h.update('\0');
    }
    return h.digest('hex');
}

function main() {
    const [simdPath, scalarPath, outPath] = process.argv.slice(2);
    if (!outPath) {
        console.error('usage: node embed.js <simd.raw.wasm> <scalar.raw.wasm> <out.js>');
        process.exit(2);
    }
    const simd = stripCustom(fs.readFileSync(simdPath));
    const scalar = stripCustom(fs.readFileSync(scalarPath));
    fs.writeFileSync(path.join(path.dirname(simdPath), 'audioclass-simd.wasm'), simd);
    fs.writeFileSync(path.join(path.dirname(scalarPath), 'audioclass-scalar.wasm'), scalar);

    const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
    const abi = Number(/#define AC_ABI_VERSION (\d+)/.exec(fs.readFileSync(path.join(__dirname, 'audioclass.h'), 'utf8'))[1]);

    const js = `// GENERATED by static/v2/native/audioclass/build.sh from the C sources there.
// Do not edit: change the sources and run that script. See its README.md.
//
// The two builds of the WebAssembly audio classifier, base64. workerHost.js is
// the only intended importer.

export const AUDIOCLASS_WASM_ABI = ${abi};

// sha256 of the sources these were built from; test.js compares it against the
// tree to catch a stale build.
export const AUDIOCLASS_WASM_SOURCE_SHA256 = '${sourceHash(__dirname)}';

// ${simd.length} bytes, sha256 ${sha(simd)}
export const AUDIOCLASS_WASM_SIMD = '${simd.toString('base64')}';

// ${scalar.length} bytes, sha256 ${sha(scalar)}
export const AUDIOCLASS_WASM_SCALAR = '${scalar.toString('base64')}';
`;

    fs.writeFileSync(outPath, js);
    console.log(`simd ${simd.length} B, scalar ${scalar.length} B -> ${outPath}`);
}

if (require.main === module) main();

module.exports = { sourceHash, SOURCES };
